import { HugeiconsIcon } from "@hugeicons/react";
import MinusIcon from "@hugeicons/core-free-icons/MinusIcon";
import PlusIcon from "@hugeicons/core-free-icons/PlusIcon";

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";

export default function ButtonGroupOrientation() {
  return (
    <ButtonGroup orientation="vertical" aria-label="Media controls" className="h-fit">
      <Button variant="outline" size="icon">
        <HugeiconsIcon icon={PlusIcon} />
      </Button>
      <Button variant="outline" size="icon">
        <HugeiconsIcon icon={MinusIcon} />
      </Button>
    </ButtonGroup>
  );
}

import ExampleButtonGroupOrientation from "../examples/button-group-orientation";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleButtonGroupOrientation />
  </div>
);

export default Example;
